CREATE FUNCTION public.replace_trade_game_days(days jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE today date; BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Not authorized'; END IF; today:=(now() AT TIME ZONE 'America/New_York')::date; PERFORM pg_advisory_xact_lock(903421); IF jsonb_array_length(days)<1 THEN RAISE EXCEPTION 'Official game days required'; END IF; DELETE FROM official_game_days WHERE game_date>=today; INSERT INTO official_game_days(club_id,game_date) SELECT DISTINCT d.club_id,d.game_date FROM jsonb_to_recordset(days) AS d(club_id text,game_date date) ON CONFLICT DO NOTHING; INSERT INTO schedule_checks(check_date,checked_at) VALUES(today,now()) ON CONFLICT(check_date) DO UPDATE SET checked_at=excluded.checked_at; END $$; REVOKE ALL ON FUNCTION public.replace_trade_game_days(jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.replace_trade_game_days(jsonb) TO service_role;